import 'dart:async';

import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('NewsListPage', () {
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final cachedItems = [
      NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
      NewsModel(title: 'Заголовок 2', link: 'https://example.com/2', date: DateTime.now()),
    ];

    final freshItems = [
      NewsModel(title: 'Свежая новость', link: 'https://example.com/fresh', date: DateTime.now()),
    ];

    Widget buildPage() => buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        );

    setUp(() {
      when(mockNewsRepository.loadNewsFeed(NewsFeedFilter.all)).thenAnswer((_) async => cachedItems);
      when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true))).thenAnswer((_) async => freshItems);
      when(mockNewsRepository.saveNewsList(any)).thenAnswer((_) async {});
    });

    testWidgets('should display all news items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(buildPage());
      await tester.pumpAndSettle();

      expect(find.text('Заголовок 1'), findsOneWidget);
      expect(find.text('Заголовок 2'), findsOneWidget);
      expect(find.text('Заголовок 3'), findsNothing);
    });

    testWidgets('should read cached feed without forcing network refresh', (WidgetTester tester) async {
      await tester.pumpWidget(buildPage());
      await tester.pumpAndSettle();

      verify(mockNewsRepository.loadNewsFeed(NewsFeedFilter.all)).called(1);
    });

    testWidgets('should show cached feed before the network response arrives', (WidgetTester tester) async {
      final Completer<List<NewsModel>> networkResponse = Completer<List<NewsModel>>();
      when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)))
          .thenAnswer((_) => networkResponse.future);

      await tester.pumpWidget(buildPage());
      await tester.pump();

      expect(find.text('Заголовок 1'), findsOneWidget);
      expect(find.text('Заголовок 2'), findsOneWidget);
      expect(find.text('Свежая новость'), findsNothing);

      networkResponse.complete(freshItems);
      await tester.pumpAndSettle();

      expect(find.text('Свежая новость'), findsOneWidget);
      expect(find.text('Заголовок 1'), findsNothing);
    });
  });
}

